def carry(apps, schema_editor):
    """Visits paid with 1.11 (one invoice on the visit) become one payment holding all their lines."""
    Visit, VisitPayment, VisitLine = apps.get_model("clinic", "Visit"), apps.get_model("clinic", "VisitPayment"), apps.get_model("clinic", "VisitLine")
    for v in Visit.objects.filter(order__isnull=False):
        p = VisitPayment.objects.create(visit=v, order_id=v.order_id, share_entry_id=v.share_entry_id, total=v.total, discount=v.discount,
                                        share=v.doctor_share, cancelled=v.state != "paid", by=v.paid_by)
        if v.state == "paid":
            VisitLine.objects.filter(visit=v).update(payment=p)


